import React, { useState, useEffect, useMemo } from 'react';
import { Ghost, Plus, BookOpen, AlertTriangle, ArrowLeft } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import CircularGallery from '../components/CircularGallery';
import StoryForm from '../components/StoryForm';
import StoryModal from '../components/StoryModal';
import { sampleStories } from '../data/sampleStories';

function MainApp() {
  const navigate = useNavigate();
  const [stories, setStories] = useState(() => {
    const saved = localStorage.getItem('horrorStories');
    return saved ? JSON.parse(saved) : sampleStories;
  });
  const [showForm, setShowForm] = useState(false);
  const [activeTab, setActiveTab] = useState('feed');
  const [selectedStory, setSelectedStory] = useState(null);

  useEffect(() => {
    localStorage.setItem('horrorStories', JSON.stringify(stories));
  }, [stories]);

  const addStory = (newStory) => {
    const story = {
      id: Date.now(),
      ...newStory,
      likes: 0,
      comments: [],
      timestamp: new Date().toISOString(),
    };
    setStories([story, ...stories]);
    setShowForm(false);
  };

  const addComment = (storyId, comment) => {
    setStories(stories.map(story => {
      if (story.id === storyId) {
        return {
          ...story,
          comments: [...story.comments, {
            id: Date.now(),
            text: comment,
            author: 'Anonymous',
            timestamp: new Date().toISOString(),
          }]
        };
      }
      return story;
    }));
  };

  const likeStory = (storyId) => {
    setStories(stories.map(story => 
      story.id === storyId ? { ...story, likes: story.likes + 1 } : story
    ));
  };

  const handleLike = () => {
    if (selectedStory) {
      likeStory(selectedStory.id);
      setSelectedStory(prev => prev ? { ...prev, likes: prev.likes + 1 } : null);
    }
  };

  const handleComment = (comment) => {
    if (selectedStory) {
      addComment(selectedStory.id, comment);
      setSelectedStory(prev => {
        if (!prev) return null;
        return {
          ...prev,
          comments: [...prev.comments, {
            id: Date.now(),
            text: comment,
            author: 'Anonymous',
            timestamp: new Date().toISOString(),
          }]
        };
      });
    }
  };

  const galleryItems = useMemo(() => {
    return stories.map((story, index) => ({
      image: '/default-story-card.jpg',
      text: story.title,
      storyId: story.id
    }));
  }, [stories]);

  return (
    <div className="min-h-screen bg-horror-black">
      {/* Background Effects */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-20 left-10 w-64 h-64 blood-splatter opacity-30"></div>
        <div className="absolute top-40 right-20 w-96 h-96 blood-splatter opacity-20"></div>
        <div className="absolute bottom-40 left-1/4 w-48 h-48 blood-splatter opacity-25"></div>
      </div>

      {/* Header */}
      <header className="relative z-10 border-b border-horror-blood/30 bg-horror-darker/80 backdrop-blur-sm">
        <div className="max-w-6xl mx-auto px-4 py-4">
          <div className="flex items-center justify-between">
            <button
              onClick={() => navigate('/')}
              className="p-2 text-horror-muted hover:text-horror-red transition-colors rounded"
              title="Back to Landing"
            >
              <ArrowLeft className="w-5 h-5" />
            </button>
            <button
              onClick={() => setShowForm(!showForm)}
              className="font-horror flex items-center gap-2 px-4 py-2 bg-horror-red hover:bg-horror-blood text-white rounded transition-all duration-300 horror-card glitch-hover"
            >
              <Plus className="w-5 h-5" />
              <span className="hidden sm:inline">Share Experience</span>
            </button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="relative z-10 max-w-6xl mx-auto px-4 py-4">
        {showForm ? (
          <StoryForm 
            onSubmit={addStory} 
            onCancel={() => setShowForm(false)}
          />
        ) : activeTab === 'rules' ? (
          <div className="max-w-2xl mx-auto">
            <div className="horror-card bg-horror-dark rounded-lg p-8">
              <h2 className="font-horror text-3xl text-horror-red mb-6 text-glow">
                Enter at Your Own Risk
              </h2>
              <div className="space-y-4 text-gray-300 font-body">
                <p className="flex items-start gap-3">
                  <span className="text-horror-red font-bold">1.</span>
                  <span>Be respectful of others' experiences. These are real fears people are sharing.</span>
                </p>
                <p className="flex items-start gap-3">
                  <span className="text-horror-red font-bold">2.</span>
                  <span>No graphic content, gore, or explicit violence. Psychological horror only.</span>
                </p>
                <p className="flex items-start gap-3">
                  <span className="text-horror-red font-bold">3.</span>
                  <span>Keep stories believable. The best horror feels like it could happen to anyone.</span>
                </p>
                <p className="flex items-start gap-3">
                  <span className="text-horror-red font-bold">4.</span>
                  <span>Trigger warnings are appreciated for sensitive topics.</span>
                </p>
                <p className="flex items-start gap-3">
                  <span className="text-horror-red font-bold">5.</span>
                  <span>Don't break character in comments. Maintain the atmosphere.</span>
                </p>
              </div>
              <div className="mt-8 p-4 bg-horror-red/10 border border-horror-red/30 rounded">
                <p className="text-horror-accent text-sm text-center italic">
                  "We do not own the darkness. We merely give it a place to speak."
                </p>
              </div>
            </div>
          </div>
        ) : (
          <div style={{ height: '450px', position: 'relative' }}>
            <CircularGallery 
              items={galleryItems}
              bend={3}
              textColor="#ffffff"
              borderRadius={0.05}
              scrollEase={0.02}
              font="bold 30px Creepster"
              onCardClick={(item) => {
                const story = stories.find(s => s.id === item.storyId);
                if (story) setSelectedStory(story);
              }}
            />
          </div>
        )}
      </main>

      {/* Fog Effect */}
      <div className="fog"></div>

      {/* Footer */}
      <footer className="relative z-10 border-t border-horror-blood/20 bg-horror-darker py-6 mt-16">
        <div className="max-w-6xl mx-auto px-4 text-center">
          <p className="text-horror-muted text-sm font-body">
            Once you enter, you can never truly leave...
          </p>
        </div>
      </footer>

      {/* Story Modal */}
      {selectedStory && (
        <StoryModal
          story={selectedStory}
          onClose={() => setSelectedStory(null)}
          onLike={handleLike}
          onComment={handleComment}
        />
      )}
    </div>
  );
}

export default MainApp;
